func (q *Queries) SetSecurityDepositCheckout(ctx context.Context, arg SetSecurityDepositCheckoutParams) error {
	_, err := q.db.Exec(ctx, setSecurityDepositCheckout,
		arg.ProviderToken,
		arg.PaymentPageUrl,
		arg.AuthorizationExpiresAt,
		arg.OrganizationID,
		arg.ID,
	)
	return err
}
